    root.sw = this.switches.map(s => err({ p: s.p, t: s.t, m: s.m, r: s.r, inv: s.inv }, s));
    root.pir = this.sensors.map(s => err({ n: s.n, p: s.p, en: s.en, night: s.night, undo: s.undo, hold: s.hold, a: s.a.map(a => a.slice()) }, s));
