    seg.sel = getBoolVal(elem.sel, seg.sel); seg.rev = getBoolVal(elem.rev, seg.rev); seg.mi = getBoolVal(elem.mi, seg.mi);
    seg.si = constrain(orInt(elem.si, seg.si), 0, 3); seg.m12 = orInt(elem.m12, seg.m12); seg.set = constrain(orInt(elem.set, seg.set), 0, 3);
