    if ((v = getVal(elem.sx, seg.sx)) !== null) seg.sx = v;
    if ((v = getVal(elem.ix, seg.ix)) !== null) seg.ix = v;
    if ((v = getVal(elem.pal, seg.pal, 0, this.S.FIXED_PALETTE_COUNT)) !== null) this.setPalette(seg, v);
    if ((v = getVal(elem.c1, seg.c1)) !== null) seg.c1 = v;
    if ((v = getVal(elem.c2, seg.c2)) !== null) seg.c2 = v;
