    if (this.S.hasAR && isObj(root.AudioReactive)) {
      if (typeof root.AudioReactive.enabled === 'boolean') this.ar.enabled = root.AudioReactive.enabled;
      if (isInt(root.AudioReactive.inputLevel)) this.ar.inputLevel = constrain(root.AudioReactive.inputLevel, 0, 255);
    }
